+
+#[test]
+fn derive_reports_tuple_fields() {
+    assert_eq!(Tuple::field_names(), &["0", "1"]);
+}
+
+#[test]
+fn derive_reports_unit_fields() {
+    let empty: &[&str] = &[];
+    assert_eq!(Unit::field_names(), empty);
+}
+
+#[test]
+fn function_like_macro_emits_struct() {
+    assert_eq!(Generated::field_names(), &["x", "y"]);
