```rust
//! `codegen-macro` demonstrates generating Rust source code as a token stream
//! from a procedural macro.

use proc_macro::TokenStream;
use proc_macro2::TokenStream as TokenStream2;
use quote::{format_ident, quote};
use syn::{parse_macro_input, Data, DeriveInput, Fields, Ident, LitStr};

/// Derive macro that implements `Describe` for a struct or enum.
#[proc_macro_derive(Describe)]
pub fn derive_describe(input: TokenStream) -> TokenStream {
    let input = parse_macro_input!(input as DeriveInput);
    expand_describe(&input)
        .unwrap_or_else(syn::Error::into_compile_error)
        .into()
}

fn expand_describe(input: &DeriveInput) -> syn::Result<TokenStream2> {
    let name = &input.ident;
    let (impl_generics, ty_generics, where_clause) = input.generics.split_for_impl();

    let fields = match &input.data {
        Data::Struct(data) => match &data.fields {
            Fields::Named(fields) => fields
                .named
                .iter()
                .map(|f| f.ident.as_ref().expect("named field").to_string())
                .collect::<Vec<_>>(),
            Fields::Unnamed(fields) => (0..fields.unnamed.len())
                .map(|i| i.to_string())
                .collect::<Vec<_>>(),
            Fields::Unit => Vec::new(),
        },
        _ => Vec::new(),
    };

    let field_names = fields.iter();
    let expanded = quote! {
        impl #impl_generics ::codegen_macro::Describe for #name #ty_generics #where_clause {
            fn field_names() -> &'static [&'static str] {
                &[#(#field_names),*]
            }
        }
    };
    Ok(expanded)
}
```

